<script setup>
import {ref as paginationRef} from 'vue'
const listPageSize=paginationRef(20)
import ListPagination from '../../shared/components/ListPagination.vue'
import DataTable from "../../shared/components/DataTable.vue"

import {useTableLayout} from '../../shared/composables/tableLayout.js'
const {pinTableActions}=useTableLayout()



import {computed, onActivated, onDeactivated, onBeforeUnmount, onMounted, ref, watch} from 'vue'
import {useRoute, useRouter} from 'vue-router'
import {api, openWorkspace, post} from '../api.js'
import {toast} from '../../shared/composables/toast.js'


import PageHeader from '../../shared/components/PageHeader.vue'
import HelpTip from '../../shared/components/HelpTip.vue'
import WorkDeliveryEditor from '../../deploy/components/WorkDeliveryEditor.vue'
import ResolveWorkItemDialog from '../components/ResolveWorkItemDialog.vue'
import ReleaseMarkDialog from '../components/ReleaseMarkDialog.vue'
import {workOrigin} from '../navigation.js'
import {fieldLabel, issueStatus, sourcePerson} from '../issueFields.js'
import {issueDate} from '../../shared/issuePresentation.js'
import {browserView} from '../../shared/viewMemory.js'
defineOptions({name:'ResearchWorkItems'})
const props=defineProps({embedded:Boolean,initialMine:Boolean})
const route=useRoute(),router=useRouter(),busy=ref(false),opening=ref(''),page=ref(1),data=ref({items:[],total:0,page:1,total_exact:true}),people=ref([]),status=ref(''),person=ref(''),role=ref('assigned_to'),intent=ref(''),mine=ref(false),me=ref({aliases:[]}),quick=ref('all'),order=ref('updated_desc'),dictionaries=ref({}),sources=ref([]),source=ref(''),product=ref('0'),productNames=ref({}),peopleNames=ref({}),loadError=ref(''),cursors=ref([''])
let queryGeneration=0,queryController,viewMemory,viewReady=false
const viewDefaults={quick:'all',order:'updated_desc'}
function rememberView(){if(viewReady)viewMemory?.write(Object.fromEntries(Object.entries(viewFields).map(([key,value])=>[key,value.value])),viewDefaults)}
const releaseMarkRecord=ref(null)
async function openReleaseMark(w){if(opening.value||!hasIdentity.value)return;const key=w.source+':'+(w.external_id||w.id);opening.value=key;try{const item=w.id?w:await post('research/work-items/attach',{connection:w.source.slice(7),external_id:w.external_id,kind:w.kind});const state=await api('research/work-items/'+item.id+'/release-mark');if(!state.can_mark){toast('仅相关成员或管理员可维护已上线标记','warning');return}releaseMarkRecord.value={item:{...w,...item},mark:state.mark,target:!w.release_mark?.marked}}catch(e){toast(e.message,'error')}finally{opening.value=''}}
function releaseMarkSaved(){releaseMarkRecord.value=null;load(true);if(window.parent!==window)window.parent.postMessage({type:'work-item.changed'},location.origin)}
const resolving=ref(null),deliveryItem=ref(null),deliveryOpen=ref(false),deliveryServices=ref([]),deliveryMe=ref({})
const canManageDelivery=value=>deliveryMe.value.role==='admin'||value?.owner===deliveryMe.value.username
const relation=ref(''),followingBusy=ref('')
const viewFields={quick,order}
watch(Object.values(viewFields),rememberView,{flush:'post'})
function resolveState(value){if(window.parent!==window)window.parent.postMessage({type:'workspace.dirty',...value},location.origin)}
function resolved(){resolving.value=null;load()}
const remoteSource=computed(()=>source.value&&source.value!=='manual')
// Use the live source dictionary for both row labels and raw-code filters.
// Replace fields rather than retaining labels from an earlier identity/read.
watch(data,result=>{if(remoteSource.value&&result.field_labels){const key='zentao:'+source.value;dictionaries.value={...dictionaries.value,[key]:{...dictionaries.value[key],...result.field_labels}}}},{flush:'sync'})
const sourceOptions=computed(()=>[{value:'',label:'全部来源'},{value:'manual',label:'平台自建'},...sources.value.map(s=>({value:s.name,label:s.name+'（Bug）'}))])
const nextAvailable=computed(()=>data.value.has_more??page.value*listPageSize.value<data.value.total)
const quickViews=[{value:'all',label:'全部'},{value:'assigned',label:'指派给我'},{value:'participating',label:'我参与的'},{value:'following',label:'我关注的'},{value:'release',label:'与我相关的待上线'},{value:'resolved',label:'由我解决'},{value:'undecided',label:'上线待确认'}]
const hasIdentity=computed(()=>me.value.auth_enabled!==false&&me.value.actor&&me.value.actor!=='local')
async function load(reset=false){const generation=++queryGeneration;queryController?.abort();const controller=new AbortController();queryController=controller;busy.value=true;loadError.value='';if(reset){page.value=1;cursors.value=['']}try{const query=new URLSearchParams({relation:relation.value,connection:source.value,product:remoteSource.value?product.value:'',mine:mine.value?'1':'',status:status.value,person:person.value,person_role:role.value,release_required:intent.value,order:order.value,page:page.value,page_size:listPageSize.value,cursor:cursors.value[page.value-1]||''});if(quick.value==='release')query.set('delivery','pending_release');const result=await api('research/work-items/page?'+query,{signal:controller.signal});if(generation!==queryGeneration)return;data.value=result;page.value=result.page;if(result.query_mode==='candidate_batch'){productNames.value={...(result.products||{}),...productNames.value};peopleNames.value={...peopleNames.value,...(result.people||{})}}else{productNames.value=result.products||{};peopleNames.value=result.people||{}}people.value=Object.keys({...(!remoteSource.value?me.value.assignees||{}:{}),...peopleNames.value}).filter(p=>p&&p!=='closed');cursors.value[page.value]=result.next_cursor||''}catch(e){if(generation!==queryGeneration||controller.signal.aborted)return;data.value={items:[],total:0,page:page.value,has_more:false};loadError.value=e.message;toast(e.message,'error',{duration:6000})}finally{if(generation===queryGeneration)busy.value=false}}
function myAccount(){return me.value.connections?.find(c=>c.name===source.value)?.account||me.value.aliases.find(a=>people.value.includes(a))||me.value.actor}
function chooseQuick(value,query=true){if(value!=='all'&&!hasIdentity.value){toast('请先登录平台，再使用我的筛选','warning');return}quick.value=value;relation.value=['participating','following'].includes(value)?value:['release','undecided'].includes(value)?'related':'';mine.value=value!=='all'&&!relation.value;person.value=mine.value?myAccount():'';role.value=value==='resolved'?'resolved_by':'assigned_to';status.value=value==='assigned'?'active':'';intent.value=value==='release'?'yes':value==='undecided'?'unknown':'';if(query)load(true)}
async function follow(w){if(followingBusy.value)return;if(!hasIdentity.value){toast('请先登录后关注工作项','warning');return}const key=w.source+':'+(w.external_id||w.id);followingBusy.value=key;try{const item=w.id?w:await post('research/work-items/attach',{connection:w.source.slice(7),external_id:w.external_id,kind:w.kind});const result=await post('research/work-items/'+item.id+'/follow',{following:!w.following},'PUT');w.id=item.id;w.following=result.following;toast(result.following?'已关注；转派后仍可追踪交付':'已取消关注，不影响参与记录','success');if(quick.value==='following'&&!result.following)load()}catch(e){toast(e.message,'error')}finally{followingBusy.value=''}}
const columnSort=field=>({sortDirections:['ascend','descend'],sorter:true,sortOrder:order.value===field+'_asc'?'ascend':order.value===field+'_desc'?'descend':''})
function sort(field,direction){order.value=direction?field+(direction==='ascend'?'_asc':'_desc'):'updated_desc';load(true)}
function changePage(value){page.value=value;load()}
async function open(item,action=''){if(opening.value)return;if(action==='resolve'){resolving.value=item;return}const key=item.source+':'+(item.external_id||item.id);opening.value=key;try{const reference=item.source.startsWith('zentao:')?await post('research/work-items/attach',{connection:item.source.slice(7),external_id:item.external_id,kind:item.kind}):item;if(action==='changes'){[deliveryServices.value,deliveryMe.value]=await Promise.all([api('services'),api('/api/me')]);deliveryItem.value={...item,...reference};deliveryOpen.value=true;return}await router.push({path:'/work/'+reference.id,query:{...(action?{action}:{}),...(props.embedded?{return:'inbox'}:{}),return_to:workOrigin(route,props.embedded)}})}catch(e){toast(e.message,'error')}finally{opening.value=''}}
function personLabel(value,item){return sourcePerson(value,item?.source==='manual'?me.value.people||{}:peopleNames.value)}
function changed(e){if(e.origin===location.origin&&e.data?.type==='work-item.changed')load()}
onActivated(()=>{if(data.value.items.length)load()})
onDeactivated(()=>resolving.value=null)
onMounted(async()=>{
 window.addEventListener('message',changed)
 try{
  [me.value,sources.value]=await Promise.all([api('research/overview'),api('research/work-items/sources')])
  source.value='';product.value='0'
  dictionaries.value=Object.fromEntries((me.value.connections||[]).map(c=>['zentao:'+c.name,c.field_labels||{}]))
  if((props.initialMine||route.query.mine==='1')&&hasIdentity.value){mine.value=true;quick.value='assigned';person.value=myAccount()}
  viewMemory=browserView('research:work:'+(props.embedded?'personal':'all'),me.value.actor||'local')
  const remembered=viewMemory.read({...viewDefaults,...Object.fromEntries(Object.entries(viewFields).map(([key,value])=>[key,value.value]))})
  for(const [key,value] of Object.entries(remembered))viewFields[key].value=value
  if(!sourceOptions.value.some(s=>s.value===source.value)){source.value='';product.value='0';person.value='';mine.value=false;quick.value='all';relation.value=''}
  if(!hasIdentity.value){mine.value=false;relation.value='';quick.value='all'}
  chooseQuick(quickViews.some(v=>v.value===route.query.quick)?route.query.quick:quick.value,false)
  viewReady=true;await load()
 }catch(e){loadError.value=e.message;toast(e.message,'error')}
})
onBeforeUnmount(()=>{rememberView();++queryGeneration;queryController?.abort();window.removeEventListener('message',changed)})
defineExpose({reload:load})





import {Badge,Button,Card,CardAction,CardContent,CardFooter,CardHeader,CardTitle,DropdownMenu,DropdownMenuContent,DropdownMenuItem,DropdownMenuTrigger,Empty,EmptyContent,EmptyDescription,EmptyHeader,Field,FieldLabel,Input,Spinner,Table,TableBody,TableCell,TableHead,TableHeader,TableRow,Tabs,TabsList,TabsTrigger} from '../../shared/shadcn-ui.js'



import {ArrowUpIcon,ArrowDownIcon,ArrowUpDownIcon} from '@lucide/vue'
</script>
<template><section :class="{'embedded-work-list':embedded,'flex-1':!embedded}" class="research-work-items flex min-h-0 min-w-0 flex-col gap-2"><PageHeader v-if="!embedded" compact class="shrink-0 mb-0!" title="需求与 Bug"><template #actions><Button variant="outline" size="sm" @click="router.push('/work/delivery')">待上线与批量交付</Button><Button @click="router.push({path:'/work/new',query:{return_to:workOrigin(route)}})" variant="default" size="sm" type="button">＋ 新建工作项</Button></template></PageHeader><div class="work-quick-filters shrink-0 flex min-w-0 items-start gap-2 border-b pb-0.5"><Tabs class="min-w-0" :model-value="quick" @update:model-value="chooseQuick($event)"><TabsList variant="line" class="h-auto! max-w-full flex-wrap gap-y-1"><TabsTrigger class="h-9" v-for="v in quickViews" :key="v.value" :value="v.value">{{v.label}}</TabsTrigger></TabsList></Tabs><div class="shrink-0 pt-1"><HelpTip text="实时查询来源连接与平台自建的需求和 Bug，展示允许范围内的全部产品。与我相关的待上线是参与或关注的生产交付候选。已关闭、测试成功不代表已上线；可人工标记已上线，误操作可在全部列表撤销。生产由环境用途配置决定。"/></div></div><DataTable :fill="!embedded" compact :loading="busy||!!opening" :rows="(((data.items)||[]).map((w,rowIndex)=>({...w,__rowKey:w.source+':'+(w.external_id||w.id)}))||[])" :columns="[{id:'c0',label:&quot;编号 / 类型&quot;,size:104,minSize:64,required:true,defaultHidden:false,flex:false,selection:false,pin:'left'},{id:'c1',label:&quot;标题&quot;,size:300,minSize:160,required:true,defaultHidden:false,flex:true,selection:false,pin:'left'},{id:'c2',label:&quot;状态&quot;,size:76,minSize:64,required:false,defaultHidden:false,flex:false,selection:false,pin:false},{id:'c3',label:&quot;指派给&quot;,size:96,minSize:64,required:false,defaultHidden:false,flex:false,selection:false,pin:false},{id:'c4',ariaSort:((columnSort('severity'))?.sortOrder==='ascend'?'ascending':(columnSort('severity'))?.sortOrder==='descend'?'descending':'none'),label:&quot;级别&quot;,size:72,minSize:64,required:true,defaultHidden:false,flex:false,selection:false,pin:false},{id:'c5',ariaSort:((columnSort('priority'))?.sortOrder==='ascend'?'ascending':(columnSort('priority'))?.sortOrder==='descend'?'descending':'none'),label:&quot;优先级&quot;,size:88,minSize:64,required:true,defaultHidden:false,flex:false,selection:false,pin:false},{id:'c6',label:&quot;解决人&quot;,size:Math.max(80,Math.min(160,112)),minSize:64,required:false,defaultHidden:true,flex:false,selection:false,pin:false},{id:'c7',ariaSort:((columnSort('resolution'))?.sortOrder==='ascend'?'ascending':(columnSort('resolution'))?.sortOrder==='descend'?'descending':'none'),label:&quot;方案&quot;,size:80,minSize:64,required:true,defaultHidden:false,flex:false,selection:false,pin:false},{id:'c8',label:&quot;生产交付&quot;,size:Math.max(80,Math.min(160,112)),minSize:64,required:false,defaultHidden:true,flex:false,selection:false,pin:false},{id:'c9',ariaSort:((columnSort('updated'))?.sortOrder==='ascend'?'ascending':(columnSort('updated'))?.sortOrder==='descend'?'descending':'none'),label:&quot;来源更新时间&quot;,size:Math.max(80,Math.min(160,156)),minSize:64,required:false,defaultHidden:true,flex:false,selection:false,pin:false},{id:'c10',label:&quot;操作&quot;,size:quick==='release'?240:144,minSize:64,required:true,defaultHidden:false,flex:false,selection:false,pin:'right'}]" table-key="research-pages-WorkItems-0" :row-key="(record,rowIndex)=>typeof (&quot;__rowKey&quot;)==='function'?(&quot;__rowKey&quot;)(record):record[&quot;__rowKey&quot;]??rowIndex"><template #toolbar><span v-if="busy" role="status" class="mr-auto flex items-center gap-2 text-xs text-muted-foreground"><Spinner/>正在读取工作项</span><Button variant="outline" size="sm" :disabled="busy||!!opening" @click="load()"><Spinner v-if="busy"/>刷新</Button></template><template #header-c0>编号 / 类型</template><template #cell-c0="{record,rowIndex}"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:w,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{w.external_id||'#'+w.id}}<small>{{w.kind==='bug'?'Bug':'需求'}} · {{w.source==='manual'?'自定义':'来源平台'}}</small></div></template></div></template><template #header-c1>标题</template><template #cell-c1="{record,rowIndex}"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:w,rowIndex:rowIndex} in [{record,rowIndex}]"><div class="research-work-title"><div class="work-title-line"><Button :aria-label="(w.following?'取消关注 ':'关注 ')+(w.external_id||w.id)" :aria-pressed="!!w.following" @click="follow(w)" class="work-follow" variant="ghost" size="sm" type="button" :disabled="(!!followingBusy)||(followingBusy===w.source+':'+(w.external_id||w.id))"><Spinner v-if="followingBusy===w.source+':'+(w.external_id||w.id)"/>{{w.following?'★':'☆'}}</Button><Button :title="w.title" @click="open(w)" class="r-title" variant="ghost" size="sm" type="button" :disabled="(!!opening)||(opening===w.source+':'+(w.external_id||w.id))"><Spinner v-if="opening===w.source+':'+(w.external_id||w.id)"/><span class="work-title-text">{{w.title}}</span></Button></div></div></template></div></template><template #header-c2>状态</template><template #cell-c2="{record,rowIndex}"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:w,rowIndex:rowIndex} in [{record,rowIndex}]"><div><Badge :variant="((w.external_status||w.status)==='closed'?'gray':(w.external_status||w.status)==='resolved'?'green':'blue')==='red'?'destructive':'secondary'">{{issueStatus(w)}}</Badge><Badge v-if="w.release_mark?.marked" variant="outline" class="mt-1 max-w-full whitespace-normal text-left" :title="'人工标记 · '+stamp(w.release_mark.at)">已上线（人工）</Badge></div></template></div></template><template #header-c3>指派给</template><template #cell-c3="{record,rowIndex}"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:w,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{personLabel(w.assigned_to,w)}}</div></template></div></template><template #header-c4><span :aria-sort="(columnSort('severity'))?.sortOrder==='ascend'?'ascending':(columnSort('severity'))?.sortOrder==='descend'?'descending':'none'"><Button class="h-7 px-0" variant="ghost" size="sm" :disabled="!(columnSort('severity'))" @click="sort(&quot;severity&quot;,((columnSort('severity'))?.sortOrder==='ascend'?'descend':(columnSort('severity'))?.sortOrder==='descend'?'':'ascend'))">级别 <ArrowUpIcon v-if="(columnSort('severity'))?.sortOrder==='ascend'" class="size-3"/><ArrowDownIcon v-else-if="(columnSort('severity'))?.sortOrder==='descend'" class="size-3"/><ArrowUpDownIcon v-else class="size-3 opacity-50"/></Button></span></template><template #cell-c4="{record,rowIndex}"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:w,rowIndex:rowIndex} in [{record,rowIndex}]"><div><span :class="'level-'+w.severity" class="issue-level">{{fieldLabel(w,'severity',dictionaries)}}</span></div></template></div></template><template #header-c5><span :aria-sort="(columnSort('priority'))?.sortOrder==='ascend'?'ascending':(columnSort('priority'))?.sortOrder==='descend'?'descending':'none'"><Button class="h-7 px-0" variant="ghost" size="sm" :disabled="!(columnSort('priority'))" @click="sort(&quot;priority&quot;,((columnSort('priority'))?.sortOrder==='ascend'?'descend':(columnSort('priority'))?.sortOrder==='descend'?'':'ascend'))">优先级 <ArrowUpIcon v-if="(columnSort('priority'))?.sortOrder==='ascend'" class="size-3"/><ArrowDownIcon v-else-if="(columnSort('priority'))?.sortOrder==='descend'" class="size-3"/><ArrowUpDownIcon v-else class="size-3 opacity-50"/></Button></span></template><template #cell-c5="{record,rowIndex}"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:w,rowIndex:rowIndex} in [{record,rowIndex}]"><div><Badge :variant="(w.priority==1?'red':w.priority==2?'orange':'gray')==='red'?'destructive':'secondary'">{{fieldLabel(w,'priority',dictionaries)}}</Badge></div></template></div></template><template #header-c6>解决人</template><template #cell-c6="{record,rowIndex}"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:w,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{personLabel(w.resolved_by,w)}}</div></template></div></template><template #header-c7><span :aria-sort="(columnSort('resolution'))?.sortOrder==='ascend'?'ascending':(columnSort('resolution'))?.sortOrder==='descend'?'descending':'none'"><Button class="h-7 px-0" variant="ghost" size="sm" :disabled="!(columnSort('resolution'))" @click="sort(&quot;resolution&quot;,((columnSort('resolution'))?.sortOrder==='ascend'?'descend':(columnSort('resolution'))?.sortOrder==='descend'?'':'ascend'))">方案 <ArrowUpIcon v-if="(columnSort('resolution'))?.sortOrder==='ascend'" class="size-3"/><ArrowDownIcon v-else-if="(columnSort('resolution'))?.sortOrder==='descend'" class="size-3"/><ArrowUpDownIcon v-else class="size-3 opacity-50"/></Button></span></template><template #cell-c7="{record,rowIndex}"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:w,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{fieldLabel(w,'resolution',dictionaries)}}</div></template></div></template><template #header-c8>生产交付</template><template #cell-c8="{record,rowIndex}"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:w,rowIndex:rowIndex} in [{record,rowIndex}]"><div :title="w.release_reason">{{w.release_required===true?'需上线':w.release_required===false?'无需上线':'待确认'}}<small v-if="w.release_origin&&w.release_origin!=='unknown'">{{w.release_origin==='manual'?'人工调整':w.release_origin==='rule'?'规则识别':'待确认'}}</small></div></template></div></template><template #header-c9><span :aria-sort="(columnSort('updated'))?.sortOrder==='ascend'?'ascending':(columnSort('updated'))?.sortOrder==='descend'?'descending':'none'"><Button class="h-7 px-0" variant="ghost" size="sm" :disabled="!(columnSort('updated'))" @click="sort(&quot;updated&quot;,((columnSort('updated'))?.sortOrder==='ascend'?'descend':(columnSort('updated'))?.sortOrder==='descend'?'':'ascend'))">来源更新时间 <ArrowUpIcon v-if="(columnSort('updated'))?.sortOrder==='ascend'" class="size-3"/><ArrowDownIcon v-else-if="(columnSort('updated'))?.sortOrder==='descend'" class="size-3"/><ArrowUpDownIcon v-else class="size-3 opacity-50"/></Button></span></template><template #cell-c9="{record,rowIndex}"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record:w,rowIndex:rowIndex} in [{record,rowIndex}]"><div>{{issueDate(w.source_updated_at||w.updated_at)}}</div></template></div></template><template #header-c10>操作</template><template #cell-c10="{record,rowIndex}"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record:w,rowIndex:rowIndex} in [{record,rowIndex}]"><div class="cell-actions"><Button v-if="quick==='release'&&hasIdentity" @click="openReleaseMark(w)" variant="ghost" size="sm" type="button" :disabled="!!opening||busy">标记已上线</Button><Button @click="open(w,'changes')" aria-label="维护交付内容" variant="ghost" size="sm" type="button" :disabled="(!!opening)||(opening===w.source+':'+(w.external_id||w.id))"><Spinner v-if="opening===w.source+':'+(w.external_id||w.id)"/>交付内容</Button><DropdownMenu><DropdownMenuTrigger as-child><Button variant="ghost" size="sm" type="button" :disabled="(!!opening)">更多</Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem v-if="w.release_mark?.marked&&hasIdentity&&(w.following||w.participating||w.release_mark.actor===me.actor)" @select="openReleaseMark(w)">撤销已上线标记</DropdownMenuItem><DropdownMenuItem v-if="w.kind==='bug'&&w.source.startsWith('zentao:')&amp;&amp;(w.external_status==='active'||w.external_status==='resolved')" @select="(command=>open(w,command))(w.external_status==='active'?'resolve':'close')">{{w.external_status==='active'?'解决':'关闭'}}</DropdownMenuItem><DropdownMenuItem @select="(command=>open(w,command))(&quot;deliver&quot;)">发起交付</DropdownMenuItem><DropdownMenuItem v-if="w.kind==='bug'||!w.source.startsWith('zentao:')" @select="(command=>open(w,command))(&quot;