:disabled="(!nextAvailable||busy)">下一页</Button></template></div><ReleaseMarkDialog :record="releaseMarkRecord" @close="releaseMarkRecord=null" @saved="releaseMarkSaved" @state="resolveState"/><WorkDeliveryEditor :show="deliveryOpen" :item="deliveryItem" :services="deliveryServices" :work-items="data.items" :can-manage="canManageDelivery" @state="resolveState" @close="deliveryOpen=false" @saved="load()" @open-sync="openWorkspace('dbms','#/sync?work_item='+deliveryItem.id)"/><ResolveWorkItemDialog :show="!!resolving" :item="resolving" :read-identity="data.read_identity" @close="resolving=null" @saved="resolved" @state="resolveState"/></section></template>
